package io.fireflysoftware.core.insurance.policies.core.services.binding.impl;

import io.fireflysoftware.core.insurance.policies.core.services.binding.*;
import java.time.Duration;
import java.util.UUID;
import org.junit.jupiter.api.Test;
import org.springframework.security.oauth2.jwt.Jwt;
import reactor.core.publisher.Mono;
import reactor.test.StepVerifier;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.*;

/** Exact actual-chain SPI facts; constructed JWTs do not prove signature/provider/Main acceptance. */
class ActualPolicyEvidenceExchangeTest {
    Jwt claim(Jwt original,String name,Object value){return Jwt.withTokenValue(original.getTokenValue()).headers(h->h.putAll(original.getHeaders())).claims(c->c.putAll(original.getClaims())).claim(name,value).build();}
    @Test void bindOnlyOriginalAndOpaqueTenantAcquireOnlyTheExactQuoteReadTarget(){var f=new ExchangedAcceptedQuoteClientProviderTest();assertEquals("insurance:policies:bind",f.inbound().getClaimAsString("scope"));assertNotEquals(f.tenant.toString(),f.permit.actor().platformTenantId());when(f.decoder.decode(anyString())).thenReturn(Mono.just(f.target()));assertNotNull(f.context(f.factory().requireExchangedClient(f.permit),f.inbound()).block(Duration.ofSeconds(2)));assertEquals(1,f.calls.get());assertTrue(f.form.get().contains("subject_token=synthetic-subject-token"));assertEquals(f.permit.actor().platformTenantId(),f.target().getClaimAsString("tenant_id"));}
    @Test void bindOnlyOriginalAndOpaqueTenantAcquireOnlyTheExactContractReadTarget(){var f=new ExchangedPolicyContractClientProviderTest();assertEquals("insurance:policies:bind",f.inbound().getClaimAsString("scope"));assertNotEquals(f.tenant.toString(),f.permit.actor().platformTenantId());when(f.decoder.decode(anyString())).thenReturn(Mono.just(f.target()));var result=f.context(f.factory().requireCurrent(f.permit),f.inbound()).block(Duration.ofSeconds(2));assertNotNull(result);assertEquals(f.tenant,result.binding().resourceTenantId());assertEquals(1,f.calls.get());}
    @Test void quoteReadScopesCannotReplaceTheAdmittedPolicyAction(){var f=new ExchangedAcceptedQuoteClientProviderTest();StepVerifier.create(f.context(f.factory().requireExchangedClient(f.permit),claim(f.inbound(),"scope","insurance:quotes:read insurance:quotes:recover"))).expectError(PolicyBindingRefusedException.class).verify();assertEquals(0,f.calls.get());verifyNoInteractions(f.decoder);}
    @Test void contractReadScopesCannotReplaceTheAdmittedPolicyAction(){var f=new ExchangedPolicyContractClientProviderTest();StepVerifier.create(f.context(f.factory().requireCurrent(f.permit),claim(f.inbound(),"scope","contracts:read contracts:parties:read"))).expectError(PolicyBindingRefusedException.class).verify();assertEquals(0,f.calls.get());verifyNoInteractions(f.decoder);}
    @Test void resourceUuidCannotReplaceOpaqueTenantOnTheQuoteTarget(){var f=new ExchangedAcceptedQuoteClientProviderTest();when(f.decoder.decode(anyString())).thenReturn(Mono.just(claim(f.target(),"tenant_id",f.tenant.toString())));StepVerifier.create(f.context(f.factory().requireExchangedClient(f.permit),f.inbound())).expectError(PolicyBindingRefusedException.class).verify();assertEquals(1,f.calls.get());}
    @Test void resourceUuidCannotReplaceOpaqueTenantOnTheContractTarget(){var f=new ExchangedPolicyContractClientProviderTest();when(f.decoder.decode(anyString())).thenReturn(Mono.just(claim(f.target(),"tenant_id",f.tenant.toString())));StepVerifier.create(f.context(f.factory().requireCurrent(f.permit),f.inbound())).expectError(PolicyBindingRefusedException.class).verify();assertEquals(1,f.calls.get());}
    @Test void foreignOriginalNamespaceCannotBorrowTheAdmittedQuoteMapping(){var f=new ExchangedAcceptedQuoteClientProviderTest();StepVerifier.create(f.context(f.factory().requireExchangedClient(f.permit),claim(f.inbound(),"tenant_id","another:opaque:tenant"))).expectError(PolicyBindingRefusedException.class).verify();assertEquals(0,f.calls.get());}
    @Test void foreignContractResourceBindingCannotStartExchange(){var f=new ExchangedPolicyContractClientProviderTest();var p=f.permit;var different=new PolicyBindingAdmission.Permit(p.request(),UUID.randomUUID(),p.partyId(),p.bindingId(),p.bindingVersion(),p.bindingDigest(),p.actor(),p.authorizationPolicyRevision(),p.processId(),p.correlationId(),p.observedAt(),p.observedNanos(),p.notAfter());StepVerifier.create(f.context(f.factory().requireCurrent(different),f.inbound())).expectError(PolicyBindingRefusedException.class).verify();assertEquals(0,f.calls.get());}
    @Test void anotherReturnedQuotePartyCannotPublishAClient(){var f=new ExchangedAcceptedQuoteClientProviderTest();when(f.decoder.decode(anyString())).thenReturn(Mono.just(claim(f.target(),"party_id",UUID.randomUUID().toString())));StepVerifier.create(f.context(f.factory().requireExchangedClient(f.permit),f.inbound())).expectError(PolicyBindingRefusedException.class).verify();assertEquals(1,f.calls.get());}
    @Test void anotherReturnedContractPartyCannotPublishAClient(){var f=new ExchangedPolicyContractClientProviderTest();when(f.decoder.decode(anyString())).thenReturn(Mono.just(claim(f.target(),"party_id",UUID.randomUUID().toString())));StepVerifier.create(f.context(f.factory().requireCurrent(f.permit),f.inbound())).expectError(PolicyBindingRefusedException.class).verify();assertEquals(1,f.calls.get());}
    @Test void exactIssueOnlyPolicyActionCanReadCurrentContractPrerequisites(){var f=new ExchangedPolicyContractClientProviderTest();var p=f.permit;var request=new PolicyBindingAdmission.Request(PolicyBindingAdmission.Action.ISSUE,p.request().actionId(),p.request().intentDigest(),UUID.randomUUID(),null,null,null,null);var issue=new PolicyBindingAdmission.Permit(request,p.resourceTenantId(),p.partyId(),p.bindingId(),p.bindingVersion(),p.bindingDigest(),p.actor(),p.authorizationPolicyRevision(),p.processId(),p.correlationId(),p.observedAt(),p.observedNanos(),p.notAfter());when(f.decoder.decode(anyString())).thenReturn(Mono.just(f.target()));assertNotNull(f.context(f.factory().requireCurrent(issue),claim(f.inbound(),"scope","insurance:policies:issue")).block(Duration.ofSeconds(2)));assertEquals(1,f.calls.get());}
    @Test void recoveryAuthorityCannotAcquireAMutationPrerequisiteClient(){var f=new ExchangedPolicyContractClientProviderTest();var p=f.permit;var request=new PolicyBindingAdmission.Request(PolicyBindingAdmission.Action.RECOVER,p.request().actionId(),p.request().intentDigest(),null,null,null,null,null);var recovery=new PolicyBindingAdmission.Permit(request,p.resourceTenantId(),p.partyId(),p.bindingId(),p.bindingVersion(),p.bindingDigest(),p.actor(),p.authorizationPolicyRevision(),p.processId(),p.correlationId(),p.observedAt(),p.observedNanos(),p.notAfter());StepVerifier.create(f.context(f.factory().requireCurrent(recovery),claim(f.inbound(),"scope","insurance:policies:recover insurance:policies:read"))).expectError(PolicyBindingRefusedException.class).verify();assertEquals(0,f.calls.get());}
    @Test void anAdditionalQuoteTargetScopeCannotPublishAClient(){var f=new ExchangedAcceptedQuoteClientProviderTest();when(f.decoder.decode(anyString())).thenReturn(Mono.just(claim(f.target(),"scope","insurance:quotes:read insurance:quotes:recover additional:scope")));StepVerifier.create(f.context(f.factory().requireExchangedClient(f.permit),f.inbound())).expectError(PolicyBindingRefusedException.class).verify();}
    @Test void anotherOriginalNativeClientCannotBorrowTheQuotePermit(){var f=new ExchangedAcceptedQuoteClientProviderTest();StepVerifier.create(f.context(f.factory().requireExchangedClient(f.permit),claim(f.inbound(),"client_id","another-client"))).expectError(PolicyBindingRefusedException.class).verify();assertEquals(0,f.calls.get());}
    @Test void missingIssuedTokenTypeCannotBecomeAnExchangedQuoteClient(){var f=new ExchangedAcceptedQuoteClientProviderTest();f.tokenReply.set(f.tokenReply.get().replace(",\"issued_token_type\":\"urn:ietf:params:oauth:token-type:access_token\"",""));StepVerifier.create(f.context(f.factory().requireExchangedClient(f.permit),f.inbound())).expectError(PolicyBindingRefusedException.class).verify();verifyNoInteractions(f.decoder);}
}
